import math

def check_divisibility(n):
    if n < 0:
        return False # Should not happen based on problem statement

    denominator = 2 * n - 1

    # Handle division by zero or negative denominator (only for n=0, denominator=-1)
    if denominator == 0:
        return False 

    try:
        # Calculate (n+2)! + 1. Need to handle large factorials.
        factorial_n_plus_2 = math.factorial(n + 2)
        numerator = 3 * (factorial_n_plus_2 + 1)

        if numerator % denominator == 0:
            return True
        else:
            return False
    except OverflowError:
        # For n up to 50, math.factorial should handle it if it uses large integers, 
        # but it's good practice to be aware of it. Python handles large ints automatically.
        return False

def is_prime(k):
    if k <= 1:
        return False
    if k <= 3:
        return True
    if k % 2 == 0 or k % 3 == 0:
        return False
    i = 5
    while i * i <= k:
        if k % i == 0 or k % (i + 2) == 0:
            return False
        i += 6
    return True

solutions = []
prime_solutions = {}
n_range = range(51)

print("--- Numerical Check Results ---")
for n in n_range:
    is_sol = check_divisibility(n)
    if is_sol:
        solutions.append(n)

    divisor = 2 * n - 1
    is_prime_divisor = False
    if divisor > 1 and is_prime(divisor):
        is_prime_divisor = True
        prime_solutions[n] = is_sol

    # Print summary for n up to 15 and 20 for detailed review
    if n <= 20:
        status = "Solution" if is_sol else "Not Solution"
        prime_status = " (Prime Divisor)" if is_prime_divisor and is_sol else ""
        print(f"n={n}, 2n-1={divisor}: {status}{prime_status}")

print("\n--- Summary ---")
print(f"All solutions found for n up to 50: {solutions}")
print(f"Prime Divisor Cases (n, 2n-1, Is Solution): {prime_solutions}")

